class Node:
    def __init__(self, val):
        self.val = val
        self.neighbors = []


def clone_graph(graph):
    n = len(graph)
    if n == 0:
        return []

    clones = {}

    def dfs(label):
        if label in clones:
            return clones[label]
        clone = Node(label)
        clones[label] = clone
        for neighbor_label in graph[label - 1]:
            clone.neighbors.append(dfs(neighbor_label))
        return clone

    dfs(1)

    # Make sure every node (even ones only reachable via edges) is cloned.
    for label in range(1, n + 1):
        if label not in clones:
            dfs(label)

    result = [[] for _ in range(n)]
    for label, clone in clones.items():
        result[label - 1] = sorted(neighbor.val for neighbor in clone.neighbors)
    return result

